package model

import "testing"

func TestParseCriterion(t *testing.T) {
	tests := []struct {
		name string
		raw  string
		want Criterion
	}{
		{"without kind", "build_passed=true", Criterion{Type: "build_passed", ExpectedValue: "true"}},
		{"whitespace and mixed case kind", " SaveNote @ JoUrNeY = true ", Criterion{Type: "SaveNote", ExpectedValue: "true", RequiredKind: "journey"}},
		{"comparison value", "latency@test=<=200ms", Criterion{Type: "latency", ExpectedValue: "<=200ms", RequiredKind: "test"}},
		{"delimiters in value", "payload@review=a=b@c", Criterion{Type: "payload", ExpectedValue: "a=b@c", RequiredKind: "review"}},
		{"preserve type and value case", " SaveNote = TrUe ", Criterion{Type: "SaveNote", ExpectedValue: "TrUe"}},
		// Syntax parsing accepts unknown kinds; the store validates policy.
		{"unknown kind", "x@unregistered=true", Criterion{Type: "x", ExpectedValue: "true", RequiredKind: "unregistered"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseCriterion(tt.raw)
			if err != nil {
				t.Fatalf("ParseCriterion(%q): %v", tt.raw, err)
			}
			if got != tt.want {
				t.Errorf("ParseCriterion(%q) = %+v, want %+v", tt.raw, got, tt.want)
			}
		})
	}

	for _, raw := range []string{"", "x", "=true", "x=", "x=   ", "@test=true", "x@=true"} {
		t.Run("reject/"+raw, func(t *testing.T) {
			if _, err := ParseCriterion(raw); err == nil {
				t.Errorf("ParseCriterion(%q) must reject malformed syntax", raw)
			}
		})
	}
}
package mcp

import (
	"bytes"
	"context"
	"encoding/json"
	"reflect"
	"testing"

	"github.com/goalforge/goalforge/internal/model"
)

func TestMCPCriterionContract(t *testing.T) {
	ctx := context.Background()
	server, db := fixture(t)
	setGoal := func(t *testing.T, criteria []string) bool {
		t.Helper()
		input, err := json.Marshal(map[string]any{
			"jsonrpc": "2.0", "id": 1, "method": "tools/call",
			"params": map[string]any{
				"name": "goal_set",
				"arguments": map[string]any{
					"project": "mcp-demo", "title": "criterion contract", "objective": "preserve required proof",
					"reason": "exercise criterion contract", "criteria": criteria,
				},
			},
		})
		if err != nil {
			t.Fatal(err)
		}
		var output bytes.Buffer
		if err := server.Serve(ctx, bytes.NewReader(append(input, '\n')), &output); err != nil {
			t.Fatal(err)
		}
		var envelope rpcEnvelope
		if err := json.Unmarshal(output.Bytes(), &envelope); err != nil {
			t.Fatalf("decode response %q: %v", output.String(), err)
		}
		if string(envelope.ID) != "1" || envelope.Error != nil {
			t.Fatalf("goal_set must return a tool result: %+v", envelope)
		}
		var result struct {
			IsError *bool `json:"isError"`
		}
		if err := json.Unmarshal(envelope.Result, &result); err != nil || result.IsError == nil {
			t.Fatalf("invalid tool result %s: %v", envelope.Result, err)
		}
		return *result.IsError
	}

	raw := []string{" SaveNote @ JoUrNeY = true ", "latency@test=<=200ms"}
	want := []model.Criterion{
		{Type: "SaveNote", ExpectedValue: "true", RequiredKind: "journey"},
		{Type: "latency", ExpectedValue: "<=200ms", RequiredKind: "test"},
	}
	if setGoal(t, raw) {
		t.Fatal("goal_set rejected valid criteria")
	}
	before, err := db.CurrentGoal(ctx, "P-MCP")
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(before.Criteria, want) {
		t.Fatalf("stored criteria = %+v, want %+v", before.Criteria, want)
	}

	for _, tt := range []struct {
		name string
		raw  string
	}{
		{"empty kind", "x@=true"},
		{"unknown kind", "x@unregistered=true"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			// The valid entry comes first to exercise partial-write rollback
			// when the store rejects an unknown kind.
			if !setGoal(t, []string{raw[0], tt.raw}) {
				t.Errorf("goal_set must reject %q with result.isError", tt.raw)
			}
			after, err := db.CurrentGoal(ctx, "P-MCP")
			if err != nil {
				t.Fatal(err)
			}
			// This includes the active goal's ID, version and full criteria.
			if !reflect.DeepEqual(after, before) {
				t.Errorf("rejected change altered the active goal:\nbefore: %+v\nafter: %+v", before, after)
			}
		})
	}
}
package main

import (
	"context"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/goalforge/goalforge/internal/model"
	store "github.com/goalforge/goalforge/internal/store/sqlite"
)

func TestCLICriterionContract(t *testing.T) {
	ctx := context.Background()
	repo := t.TempDir()
	gitIn(t, repo, "init", "-b", "main")
	dbPath := filepath.Join(t.TempDir(), "state.db")
	t.Setenv("GOALFORGE_DB", dbPath)
	t.Chdir(repo)
	runCLI(t, ctx, "project", "init", "--name", "criteria")

	db, err := store.Open(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = db.Close() })
	// Getwd resolves temporary-directory symlinks just as CLI dispatch does.
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	project, err := db.ProjectByPath(ctx, cwd)
	if err != nil {
		t.Fatal(err)
	}

	raw := []string{" SaveNote @ JoUrNeY = true ", "latency@test=<=200ms"}
	want := []model.Criterion{
		{Type: "SaveNote", ExpectedValue: "true", RequiredKind: "journey"},
		{Type: "latency", ExpectedValue: "<=200ms", RequiredKind: "test"},
	}
	runCLI(t, ctx, "goal", "set", "--title", "criterion contract", "--objective", "preserve required proof",
		"--criterion", raw[0], "--criterion", raw[1])
	before, err := db.CurrentGoal(ctx, project.ID)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(before.Criteria, want) {
		t.Fatalf("stored criteria = %+v, want %+v", before.Criteria, want)
	}

	for _, tt := range []struct {
		name string
		raw  string
	}{
		{"empty kind", "x@=true"},
		{"unknown kind", "x@unregistered=true"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			// Put a valid criterion first so an unknown kind exercises rollback
			// after the store has started writing the replacement goal.
			output, err := runCLIWithError(t, ctx, "goal", "set", "--title", "rejected replacement",
				"--objective", "must not replace the active goal", "--reason", "exercise invalid criterion",
				"--criterion", raw[0], "--criterion", tt.raw)
			if err == nil {
				t.Errorf("goal set must reject %q; output: %s", tt.raw, output)
			}
			after, err := db.CurrentGoal(ctx, project.ID)
			if err != nil {
				t.Fatal(err)
			}
			// This includes the active goal's ID, version and full criteria.
			if !reflect.DeepEqual(after, before) {
				t.Errorf("rejected change altered the active goal:\nbefore: %+v\nafter: %+v", before, after)
			}
		})
	}
}
